#!/usr/bin/env python3
"""Validate and reconcile one stock case into one desk receipt."""

import json
import os
import sys
import tempfile


FIELDS = {"id", "type", "sku", "quantity"}
TYPES = {"receipt", "ship", "reserve"}


def receipt(case_id, status, issue, on_hand=None, available=None):
    return {
        "case_id": case_id,
        "status": status,
        "on_hand": on_hand or {},
        "available": available or {},
        "issue": issue,
        "action_performed": False,
    }


def nonnegative_integer(value):
    return isinstance(value, int) and not isinstance(value, bool) and value >= 0


def reconcile(case):
    if not isinstance(case, dict):
        return receipt(None, "failed", "invalid")

    case_id = case.get("case_id")
    if "opening" not in case or "events" not in case:
        return receipt(case_id, "needs_input", "missing")

    opening = case["opening"]
    events = case["events"]
    if not isinstance(opening, dict) or not isinstance(events, list):
        return receipt(case_id, "needs_review", "invalid")
    if any(not isinstance(sku, str) or not sku or not nonnegative_integer(qty)
           for sku, qty in opening.items()):
        return receipt(case_id, "needs_review", "invalid")

    # Validate the whole submission before considering duplicate conflicts.
    for event in events:
        if not isinstance(event, dict) or set(event) != FIELDS:
            return receipt(case_id, "needs_review", "invalid")
        if not isinstance(event["id"], str) or not event["id"]:
            return receipt(case_id, "needs_review", "invalid")
        if not isinstance(event["type"], str) or event["type"] not in TYPES:
            return receipt(case_id, "needs_review", "invalid")
        if not isinstance(event["sku"], str) or event["sku"] not in opening:
            return receipt(case_id, "needs_review", "invalid")
        if not nonnegative_integer(event["quantity"]):
            return receipt(case_id, "needs_review", "invalid")

    seen = {}
    unique = []
    for event in events:
        event_id = event["id"]
        if event_id in seen:
            if event != seen[event_id]:
                return receipt(case_id, "needs_review", "conflict")
            continue
        seen[event_id] = event
        unique.append(event)

    on_hand = dict(opening)
    reserved = {sku: 0 for sku in opening}
    for event in unique:
        sku = event["sku"]
        qty = event["quantity"]
        if event["type"] == "receipt":
            on_hand[sku] += qty
        elif event["type"] == "ship":
            on_hand[sku] -= qty
        else:
            reserved[sku] += qty

    available = {sku: on_hand[sku] - reserved[sku] for sku in opening}
    if any(qty < 0 for qty in on_hand.values()) or any(
            qty < 0 for qty in available.values()):
        return receipt(case_id, "needs_review", "negative")
    return receipt(case_id, "completed", "none", on_hand, available)


def write_json(path, value):
    directory = os.path.dirname(os.path.abspath(path))
    fd, temporary = tempfile.mkstemp(prefix=".receipt-", dir=directory, text=True)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as stream:
            json.dump(value, stream, ensure_ascii=False, separators=(",", ":"))
            stream.write("\n")
        os.replace(temporary, path)
    except BaseException:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise


def main(argv):
    if len(argv) != 3:
        print("usage: reconcile.py INPUT OUTPUT", file=sys.stderr)
        return 2
    try:
        with open(argv[1], encoding="utf-8") as stream:
            case = json.load(stream)
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        print("cannot read input: {}".format(exc), file=sys.stderr)
        return 1

    try:
        result = reconcile(case)
    except Exception:
        case_id = case.get("case_id") if isinstance(case, dict) else None
        result = receipt(case_id, "failed", "invalid")
    try:
        write_json(argv[2], result)
    except OSError as exc:
        print("cannot write output: {}".format(exc), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
